"""Materialize P05 page 19–104 independent continuation notes; not a model runner."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib
import json
import re

ROOT=Path(__file__).resolve().parent
SCOPES=[('commissioned','技术开发（委托）',3,16),('cooperative','技术开发（合作）',17,33),('application_assignment','技术转让（专利申请权）',34,44),('patent_assignment','技术转让（专利权）',45,55),('patent_license','技术转让（专利实施许可）',56,67),('knowhow','技术转让（技术秘密）',68,80),('consulting','技术咨询',81,92),('technical_services','技术服务',93,104)]

def main():
    t=(ROOT/'sanitized/P05.txt').read_text(encoding='utf-8')
    boundaries={int(m.group(1)):m.start() for m in re.finditer(r'\[PAGE (\d+)\]\n',t)}
    boundaries[105]=len(t)
    scope_records={key:{'id':key,'title':title,'pages':list(range(a,b+1)),'start':boundaries[a],'end':boundaries[b+1]} for key,title,a,b in SCOPES}
    def ev(scope,begin,end=None):
        s=scope_records[scope]
        positions=[m.start() for m in re.finditer(r'\S',t[s['start']:s['end']])]
        normalized=''.join(t[s['start']+p] for p in positions)
        left=re.sub(r'\s','',begin); right=re.sub(r'\s','',end) if end else left
        a=normalized.index(left); b=normalized.index(right,a)+len(right)
        start=s['start']+positions[a]; finish=s['start']+positions[b-1]+1
        page=max(n for n,pos in boundaries.items() if n<105 and pos<=start)
        return {'quote':t[start:finish],'start':start,'end':finish,'page':page,'template_scope':scope}
    findings=[]
    def add(fid,scope,severity,perspective,risk,impact,suggestion,evidence,questions):
        findings.append({'id':fid,'template_scope':scope,'severity':severity,'perspective':perspective,'risk':risk,'impact':impact,'suggestion':suggestion,'evidence':evidence,'basis':{'status':'unverified','type':'template_text_and_conditional_business_review','note':'未查询当前法律法规/司法解释/登记实务；不作当然违法、无效或最终责任判断。空白是模板配置入口，须结合真实签署稿、交易和立场确认。'},'questions':questions})
    s='cooperative'
    add('P05-C01',s,'medium','技术风险/法务/多方关系','合作研发失败认定条件只写乙方无过错，未明确其他合作方角色','第九条开头面向合作一方或多方损失，但无过错条件仅点名乙方。若失败发生在甲方或丙方承担的工作，可能出现适用对象及证明标准争议；不是认定其他方自动免责。','按第二条工作分工明确发生失败的任务、责任主体、合理失败证明及独立评估方式；统一第九条对各方的适用对象，并与第十九条过错违约责任区分。',[ev(s,'第九条  在本合同履行中','合作各方约定按以下方式承担风险损失：'),ev(s,'2． 乙方在主观上无过错且经认定研究开发失败为合理的失败。')],['乙方是否实际承担全部研发？甲方、丙方参与任务失败时按什么条件认定？'])
    add('P05-C02',s,'high','知识产权/技术集成/业务','阶段成果、最终成果和后续改进归属需补足相互实施权限','第十五条允许独立阶段成果由完成方享权，第十六条另定最终成果，第20条允许各方后续改进。勾选归属本身不解决最终成果实施所需的其他方背景/阶段成果许可、退出和改进后的兼容问题。','列出背景、阶段、集成最终、后续成果依赖关系；分别约定实施/修改/许可范围、维护费、许可期限、退出后存续及共有决策。明确协作义务与保密边界，避免把所有权等同于完整实施权。',[ev(s,'第十五条：合作各方确定','第十六条：合作各方确定'),ev(s,'第二十条：合作各方确定','第二十一条')],['最终成果是否必须使用某一方独有模块？该方退出后其他方能否维护、销售或继续研发？'])
    s='application_assignment'
    add('P05-C03',s,'high','财务/知识产权/申请程序','申请被驳回不退已付款，需区分商业申请风险与让与方违约','第八条默认已收款不退，未收部分和特别约定待填写；第六条另有权利不侵害第三人的保证。若驳回因权属资料、提前公开或程序协作问题引起，仅采用默认不退费会产生过宽风险转移的争议。','区分诚实披露后的正常不授权风险、让与方虚假资料/权属瑕疵/不配合的责任；约定审查进度报告、答复期限、复审控制、分期节点和对应退款/赔偿，不假定第八条覆盖所有过错。',[ev(s,'第八条：双方确定','第九条：双方确定'),ev(s,'第六条：乙方应当保证','第七条')],['受让价款是否以未来授权为核心？目前审查意见、优先权和期限是否完整披露？'])
    add('P05-C04',s,'high','业务/财务/既有合同承接','原技术转让合同权利义务整体承接需要逐份确定','第二条披露已实施/已许可，第3条要求甲方保证原技术转让合同履行并承受权利义务，但未预设清单、历史违约和款项分界。不能仅凭申请权标识判断所买资产不存在既有使用或付费负担。','把每份上游/下游合同、许可范围、期限、应收应付、既有违约、变更所需协作列为附件；明确哪些义务移转、交割前后归属及无法完成变更时的处理。同步登记节点与实际履行移交。',[ev(s,'第二条：乙方在本合同签署前','第四条：为保证甲方申请专利')],['第3条原技术转让合同具体是哪些？对方当事人是上游让与人还是下游被许可人？未披露负担谁承担？'])
    s='patent_assignment'
    add('P05-C05',s,'high','法务/知识产权/财务','专利无效不承担法律责任的宽泛表述需与权利保证协调','第十条对生效后无效写成不承担法律责任，第九条又保证转让不侵犯第三人合法权益。真实交易需区分正常无效风险与隐瞒已知争议、权属瑕疵或违约，不能据默认条款直接宣布让与方任何情形均免责。','核验权属、有效期限、年费、无效/诉讼状态；把已披露风险和违约责任分别定义，约定价款调整、退款、抗辩协作和例外事项，交当地适用法律核验。',[ev(s,'第九条：乙方应当保证','第十条：乙方对本合同生效后专利权被宣告无效，不承担法律责任。')],['是否存在已知无效请求或争议？价格中专利与技术秘密各占多少？'])
    add('P05-C06',s,'high','业务/知识产权/许可关系','受让专利不自动等于排除所有他人实施','第2/3条保留并承接原许可，第4条允许约定乙方继续实施，第13条允许双方后续改进。拟购买市场独占地位时，这些条款可能使买方的商业预期落空，须审签署稿具体配置。','逐项列明存续被许可人及排他范围、乙方保留实施权限、后续改进实施所需授权；确认哪些许可须在交割前终止或调整，并将目标权利状态设为交割条件。',[ev(s,'第三条：甲方应在本合同生效后','第五条：为保证甲方有效拥有本项专利权'),ev(s,'第十三条：双方确定：','第十四条：双方确定')],['甲方买的是收入权还是独占经营空间？乙方及原被许可人交割后还能怎样实施？'])
    s='patent_license'
    add('P05-C07',s,'medium','财务/专利状态/责任计算','无效后的赔偿与不返还使用费需定义结算口径','第十一条同时规定专利无效赔偿损失但已付使用费不返还；第九条又把技术秘密/服务指导费拆入总费。若不区分收费期间、费用性质和可计入损失的项目，可能对是否抵扣或重复补偿产生争议。','约定无效发生后的停止/继续使用、未付费用和各类费用结算；明确已付款与可赔损失的关系以及另有价值的技术秘密/服务部分，并核验适用法律边界。',[ev(s,'本项专利权被国家专利行政主管机关宣布无效的','但甲方已给付乙方的使用费，不再返还。'),ev(s,'第九条：甲方向乙方支付实施该项专利权使用费','2．许可实施使用费由甲方')],['尚未实施就无效如何处理？哪些付费对应专利、秘密或服务？损失如何证明且避免双计？'])
    add('P05-C08',s,'high','业务/履约/现金流','强制开始实施期限需关联资料交付与验收条件','第12条以合同生效后天数要求开始实施，对无解释且影响提成收益的迟延设置责任；第4/5/7/8条另定资料、指导及验收。若实施所必需材料未就绪或验收失败，单纯按生效日起算易产生争议。','把实施启动依赖、资料和指导交付、验收失败整改、允许延期及通知方式写清；对让与方迟延或客观许可条件未成就设置对应调整，约定与提成计算一致的实施证据。',[ev(s,'第十二条：甲方应当在本合同生效后','第十三条'),ev(s,'第八条：双方确定','第九条')],['开始实施是试产、量产还是首笔销售？乙方提供条件未齐时如何暂停计时？'])
    s='knowhow'
    add('P05-C09',s,'high','知识产权/技术风险/退出结算','第三人通过专利公开被排除于自动解除条件，需要另定侵权及价值下降处理','第7条针对技术秘密由他人公开设置通知解除，但括号排除专利公开；第9条处理的是乙方自行申请专利并保留甲方使用，两者主体不同，不能互相替代。真实技术若遇第三人专利公开，仍需结合第6条权利保证和第19条解除约定处理。','分别约定第三人专利申请公开/授权/主张权利时的核验、抗辩、替代技术、暂停付款和退出结算；区分公开导致非秘密与实际侵权，不能见专利公开即认定侵权。',[ev(s,'第七条：在本合同履行过程中','第八条：双方确定'),ev(s,'第九条：双方确定','第十条：为保证甲方有效实施'),ev(s,'第六条：乙方保证本项技术秘密的实用性','第七条')],['技术是否已有竞争专利申请？公开后剩余秘密及应用价值如何评估？'])
    add('P05-C10',s,'high','业务/保密/知识产权','“使用权、转让权”及既有对外转让需形成明确许可范围','前言给出使用权/转让权选项，第4条披露乙方既有实施/转让，第5条规定甲方实施范围。选“转让权”并不自动说明是否独占、是否允许再许可或能否披露给关联方/供应商。若把这些概念混用，保密条款会与商业使用需要冲突。','分别定义使用/再许可/再转让权限、地域行业期限、允许接收者和保密传递；披露并处理既有安排及乙方保留权，使用清单与第8条涉密人员/责任对应。',[ev(s,'本合同乙方将其拥有','甲方，甲方受让并支付相应的使用费。'),ev(s,'第四条：乙方在本合同生效前','第六条：乙方保证')],['是否需要关联公司、代工厂或服务商实施？购买方期待独占还是普通使用？'])
    s='consulting'
    add('P05-C11',s,'high','业务决策/法务/专业责任','决策损失免责选项仅针对符合约定的咨询成果，不能扩张成所有失误免责','第9条限定成果符合合同标准后据此决策实施的损失，再给出不承担/部分/全部责任选项；第7条验收与第8条违约另行存在。真实合同需区分合规咨询下的经营风险、成果不达标和资料错误，不能把勾选第9条当作不做专业审查。','把咨询范围、输入事实、关键假设、验证深度、用途限制和交付标准写入附件；明确第8条与第9条适用分界，必要时约定更正、复核或责任分配，核验法定责任边界。',[ev(s,'第九条：双方确定','第十条：双方确定'),ev(s,'第七条：双方确定','第八条：双方确定')],['报告将支撑投资/投产还是一般参考？错误源自甲方资料还是乙方分析？如何证明“符合约定”？'])
    add('P05-C12',s,'medium','知识产权/保密/数据使用','新技术成果归属选项不等于对甲方材料的无限利用授权','第10条分别分配在合同有效期内产生的新成果，其中乙方可基于甲方资料与条件完成成果；第3条资料提供和第5条保密另存。若只填“乙方所有”，仍未明确基础材料使用目的、报告本身权利、对外复用和终止后处理。','区分原有资料、咨询报告及新增成果，限定履约目的使用、可匿名复用范围及后续许可；约定归属不解除保密义务，涉及数据时另查访问和处理依据。',[ev(s,'第十条：双方确定：','第十一条：双方确定'),ev(s,'第三条：为保证乙方有效进行技术咨询工作','1．提供技术资料：')],['乙方能否将资料用于其他客户或训练模型？甲方能否修改、转交或实施报告？'])
    s='technical_services'
    add('P05-C13',s,'high','业务履约/质量/财务','一次成果验收与持续质量期限需按服务形态衔接','第2条已有服务质量要求/质量期限，第7条另设成果验收，第4条约定付款。用于持续维护或生产系统支持时，仅填一次验收不能说明验收后质量承诺、故障修复、服务中断及重复问题责任；一次专项服务则不必机械引入SLA。','先确认一次交付还是持续服务；将质量期限起算、缺陷响应修复、复验、服务暂停及费用调整等与验收付款和第9条违约责任对应，保留必要的范围外收费机制。',[ev(s,'第二条：乙方应按下列要求完成技术服务工作','第三条：为保证乙方有效进行技术服务工作'),ev(s,'第七条：双方确定以下列标准','第八条：双方确定')],['质量期限从何时起？验收后问题如何处理？服务范围是否包含持续运行保障？'])
    add('P05-C14',s,'high','信息安全/协作资料/退出交接','技术服务中的资料和系统访问不能仅靠保密栏目控制','第3条要求甲方提供资料及工作条件，第5条主要列保密内容/人员/期限/责任，第11条解除并未自动定义资料返还、账号撤销和交接。若服务涉及生产系统、源代码或个人信息，签署稿需要补执行控制；本模板不是已违规实例。','按实际服务列明最小必要访问、授权审批、远程/外包限制、日志及事件通知、第三方工具使用、验收/终止时权限撤销与资料返还删除；与第8条新增成果权利及保密存续一并协调。',[ev(s,'第三条：为保证乙方有效进行技术服务工作','第四条：甲方向乙方支付'),ev(s,'第五条：双方确定因履行本合同应遵守的保密义务如下：'),ev(s,'第十一条：双方确定','第十二条：双方因履行')],['工作条件是否包含生产账号或真实数据？终止后谁接管账号、配置、数据和文档？'])
    for scope in scope_records.values():
        scope['reading_status']='PREVIOUS_BATCH_TEXT_READ' if scope['id']=='commissioned' else 'TEXT_READ_WITH_CONTINUATION'
        scope['findings_in_this_batch']=[f['id'] for f in findings if f['template_scope']==scope['id']]
    prior=ROOT/'reviews/batch-tech-nda.json'
    result={'reviews':[{'case_id':'P05','input_sha256':hashlib.sha256(t.encode()).hexdigest(),'review_mode':'independent_single_agent_public_template_continuation','created_at':datetime.now(timezone.utc).isoformat(),'prior_review_path':str(prior),'prior_review_sha256':hashlib.sha256(prior.read_bytes()).hexdigest(),'coverage':{'status':'SINGLE_AGENT_CONTINUATION_TEXT_READ','read_pages':list(range(19,105)),'unread_pages_in_this_batch':list(range(1,19)),'cumulative_read_pages_with_prior_batch':list(range(1,105)),'cumulative_unread_pages':[],'scope_records':list(scope_records.values()),'detail':'本批实际全文读取19–104页，1–18页已在原batch-tech-nda.json独立记录。104页尾部只有合同编号，按资料尾页保留，不推定另有完整合同。原记录PARTIAL_AUDIT不修改。合并只表明文字层104页实际读过，非逐字风险证明、六专家四轮、全量PDF版面验证或法律验收。'},'stance':'公开模板使用前的双方法律/商业配置检查，具体交易和客户立场未给定','findings':findings,'gold_label_status':'AWAITING_HUMAN_ADJUDICATION'}]}
    (ROOT/'reviews/batch-tech-continuation.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'reviews':1,'new_templates':7,'findings':len(findings),'evidence':sum(len(f['evidence']) for f in findings),'actual_read_pages_this_batch':86}))

if __name__=='__main__':main()
